def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_residual = bins * 0.25
    score = -np.square(remaining - target_residual)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_residual = bins * 0.25
    score = -np.exp(np.abs(remaining - target_residual) / (bins + 1e-8))
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = np.where(bins > 0, item / bins, np.inf)
    return np.where(remaining < 0, -np.inf, -np.abs(fill_ratio - 0.5))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, remaining)
